    shampoo: ["Shampoo", "Shampoo kommt von Hindi chāmpo, „drücken, massieren“; im 18. Jahrhundert kam es aus Indien ins Englische und bedeutete zuerst eine Massage."],
    safari: ["Safari", "Safari ist Swahili für „Reise“ – selbst ein Lehnwort aus arabisch safar."],
    ski: ["Ski", "Ski ist norwegisch, von altnordisch skíð, „Holzscheit“."],
    sauna: ["Sauna", "Sauna ist finnisch – und Finnland hat bei etwa 5,5 Millionen Einwohnern rund drei Millionen Saunen."],
    yogurt: ["Joghurt", "Yogurt ist türkisch yoğurt, verwandt mit yoğurmak, „kneten, eindicken“."],
    pajamas: ["Pyjama", "Pajamas kommt von persisch pāy-jāma, „Beinkleid“, über das Hindustani."],
    cookie: ["Keks", "Cookie kommt von niederländisch koekje, „Küchlein“, das die Niederländer von Neu-Amsterdam ins amerikanische Englisch brachten."],
    kindergarten: ["Kindergarten", "Kindergarten ist deutsch: „Garten der Kinder“, so benannt vom Pädagogen Friedrich Fröbel im Jahr 1840."],
    coach: ["Kutsche / Trainer", "Coach kommt von ungarisch kocsi, „(Wagen) aus Kocs“, einem für seine Wagen berühmten Dorf; die Bedeutung „Trainer“ kam später."],
    mammoth: ["Mammut", "Mammoth kommt von russisch mamont, vielleicht seinerseits aus dem Mansischen in Sibirien entlehnt."],
    hammock: ["Hängematte", "Hammock kommt von hamaka im Taíno, einer Sprache der Karibik; das Taíno ist ausgestorben, das Wort überlebte im Spanischen."],
